import { Injectable } from "@angular/core";
import { BehaviorSubject, Observable } from "rxjs";
import { Settings } from "./models/settings.model";
import { TagModel } from "./tags.service";

@Injectable({
    providedIn: "root",
})
export class ChromeService {
    private _domain$ = new BehaviorSubject<string>("zelf");
    private _isExtension = Boolean(typeof browser !== "undefined" && browser.storage && browser.runtime);
    private _isPopout = false;
    private _isPopout$ = new BehaviorSubject<boolean>(false);
    private _isSidePanel = false;
    private _isSidePanel$ = new BehaviorSubject<boolean>(false);
    private _accessToken$ = new BehaviorSubject<string>("");
    private _lastVerified$ = new BehaviorSubject<number>(0);
    private _hideWalletBalances$ = new BehaviorSubject<boolean>(false);
    private _myArnsDontShowAgain$ = new BehaviorSubject<boolean>(false);
    private _settings$ = new BehaviorSubject<Settings>({} as Settings);
    private _tabId?: number;
    private _tabStorageKey = "isTabOpen";
    private _wallet$ = new BehaviorSubject<TagModel>({} as TagModel);
    private _wallets$ = new BehaviorSubject<TagModel[]>([] as TagModel[]);
    private _activeTabConnected$ = new BehaviorSubject<boolean>(false);

    // In-memory cache for local storage
    private _localCache: Record<string, any> = {};
    private _cacheInitialized = false;
    private _initCachePromise: Promise<void> | null = null;

    constructor() {
        if (!this.isExtension) return;

        this._initCache();
        this._initBrowserListeners();
    }

    private async _initCache(): Promise<void> {
        if (this._cacheInitialized) return;
        if (this._initCachePromise) return this._initCachePromise;

        this._initCachePromise = browser.storage.local.get(null).then((data) => {
            this._localCache = data || {};
            this._cacheInitialized = true;
            this._hideWalletBalances$.next(this._coerceHideWalletBalances(this._localCache.hideWalletBalances));
        });

        return this._initCachePromise;
    }

    private _coerceHideWalletBalances(value: unknown): boolean {
        return value === true || value === "true";
    }

    private _initBrowserListeners(): void {
        browser.tabs.getCurrent().then((tab) => {
            this._tabId = tab?.id;

            this._isPopout = window === browser.extension.getViews({ type: "popup" })[0];
            this._isPopout$.next(this._isPopout);

            this._isSidePanel = !this._isPopout && !this._tabId;
            this._isSidePanel$.next(this._isSidePanel);
        });

        browser.tabs.onRemoved.addListener(async (closedTabId) => {
            const storedTabId = await this.getItem("tabId");

            if (storedTabId !== closedTabId) return;

            await this.setItem(this._tabStorageKey, false);
        });

        browser.tabs.onActivated.addListener(this._checkActiveTabConnection.bind(this));
        browser.tabs.onUpdated.addListener(this._checkActiveTabConnection.bind(this));
        this._checkActiveTabConnection();

        browser.storage.local.onChanged.addListener((changes) => {
            // Update local cache
            for (const [key, change] of Object.entries(changes)) {
                this._localCache[key] = change.newValue;
            }

            if (changes.lastVerified) {
                this._lastVerified$.next(changes.lastVerified.newValue as number);
            }

            if (changes.settings) {
                this._settings$.next(changes.settings.newValue as Settings);
            }

            if (changes.domain) {
                this._domain$.next(changes.domain.newValue as string);
            }

            if (changes.accessToken) {
                this._accessToken$.next(changes.accessToken.newValue as string);
            }

            if (changes.wallet) {
                this.removeItemSession("zelfKeysData");
                this.removeItemSession("zelfKeysDataTtl");
                this.removeItemSession("tokens");
                this.removeItemSession("tokensTtl");

                changes.wallet
                    ? this._wallet$.next(changes.wallet.newValue ? (new TagModel(changes.wallet.newValue) as TagModel) : ({} as TagModel))
                    : ({} as TagModel);
            }

            if (changes.wallets) {
                changes.wallets
                    ? this._wallets$.next(
                          ((changes.wallets.newValue as TagModel[]) || ([] as TagModel[]))?.map((wallet: any) => new TagModel(wallet || {}))
                      )
                    : ([] as TagModel[]);
            }

            if (changes.hideWalletBalances) {
                this._hideWalletBalances$.next(this._coerceHideWalletBalances(changes.hideWalletBalances.newValue));
            }

            if (changes.myArnsDontShowAgain) {
                this._myArnsDontShowAgain$.next(changes.myArnsDontShowAgain.newValue as boolean);
            }

            if (changes.dapp_permissions) {
                this._checkActiveTabConnection();
            }
        });

        if (!this.isExtension) {
            window.addEventListener("localstorage", (event: CustomEvent<{ key: string; oldValue: string; newValue: string }>) => {
                if (!event?.detail?.key) return;

                if (event.detail.key === "lastVerified" && event.detail.newValue !== undefined) {
                    this._lastVerified$.next(event.detail.newValue ? parseInt(event.detail.newValue) : 0);
                }

                if (event.detail.key === "settings") {
                    this._settings$.next(event.detail.newValue ? (JSON.parse(event.detail.newValue) as Settings) : ({} as Settings));
                }

                if (event.detail.key === "domain") {
                    this._domain$.next(event.detail.newValue as string);
                }

                if (event.detail.key === "accessToken") {
                    this._accessToken$.next(event.detail.newValue as string);
                }

                if (event.detail.key === "wallet") {
                    this.removeItemSession("zelfKeysData");
                    this.removeItemSession("zelfKeysDataTtl");
                    this.removeItemSession("tokens");
                    this.removeItemSession("tokensTtl");

                    event
                        ? this._wallet$.next(event.detail.newValue ? (new TagModel(JSON.parse(event.detail.newValue)) as TagModel) : ({} as TagModel))
                        : ({} as TagModel);
                }

                if (event.detail.key === "wallets") {
                    event
                        ? this._wallets$.next(
                              (((JSON.parse(event.detail.newValue) || []) as TagModel[]) || ([] as TagModel[]))?.map(
                                  (wallet: any) => new TagModel(wallet || {})
                              )
                          )
                        : ([] as TagModel[]);
                }

                if (event.detail.key === "hideWalletBalances") {
                    this._hideWalletBalances$.next(event.detail.newValue === "true");
                }

                if (event.detail.key === "myArnsDontShowAgain") {
                    this._myArnsDontShowAgain$.next(event.detail.newValue === "true");
                }
            });
        }
    }

    private async _checkActiveTabConnection(): Promise<void> {
        if (!this.isExtension) return;
        try {
            const tabs = await browser.tabs.query({ active: true, currentWindow: true });
            if (!tabs || tabs.length === 0 || !tabs[0].url) {
                this._activeTabConnected$.next(false);
                return;
            }
            const origin = new URL(tabs[0].url).origin;
            const permissions = await this.getItem("dapp_permissions");
            const isConnected = !!(permissions && permissions[origin] && permissions[origin].accounts && permissions[origin].accounts.length > 0);
            this._activeTabConnected$.next(isConnected);
        } catch (e) {
            this._activeTabConnected$.next(false);
        }
    }

    get isExtension(): boolean {
        return this._isExtension;
    }

    get isPopout(): boolean {
        return this._isPopout;
    }

    get isPopout$(): Observable<boolean> {
        return this._isPopout$.asObservable();
    }

    get isSidePanel(): boolean {
        return this._isSidePanel;
    }

    get isSidePanel$(): Observable<boolean> {
        return this._isSidePanel$.asObservable();
    }

    get onAccessTokenChanged$(): Observable<string> {
        return this._accessToken$.asObservable();
    }

    get onDomainChanged$(): Observable<string> {
        return this._domain$.asObservable();
    }

    get onLastVerifiedChanged$(): Observable<number> {
        return this._lastVerified$.asObservable();
    }

    get onHideWalletBalancesChanged$(): Observable<boolean> {
        return this._hideWalletBalances$.asObservable();
    }

    get onMyArnsDontShowAgainChanged$(): Observable<boolean> {
        return this._myArnsDontShowAgain$.asObservable();
    }

    get onSettingsChanged$(): Observable<Settings> {
        return this._settings$.asObservable();
    }

    get onWalletChanged$(): Observable<TagModel> {
        return this._wallet$.asObservable();
    }

    get onWalletsChanged$(): Observable<TagModel[]> {
        return this._wallets$.asObservable();
    }

    get activeTabConnected$(): Observable<boolean> {
        return this._activeTabConnected$.asObservable();
    }

    async setHideWalletBalances(hidden: boolean): Promise<void> {
        await this.setItem("hideWalletBalances", hidden);

        this._hideWalletBalances$.next(hidden);
    }

    async closeTab(): Promise<void> {
        if (!this.isExtension || !this._tabId) return;

        browser.tabs.remove(this._tabId);
    }

    async copyToClipboard(value: string): Promise<void> {
        if (navigator?.clipboard) {
            navigator?.clipboard.writeText(value);

            return;
        }

        const input = document.createElement("input");

        input.value = value;

        document.body.appendChild(input);

        input.select();

        document.execCommand("copy");
        document.body.removeChild(input);
    }

    async getItem<T = any>(key: string, overrideSource?: string): Promise<T> {
        let source = this.isExtension ? "extension" : "web";

        if (overrideSource) {
            source = ["extension", "web"].includes(overrideSource) ? overrideSource : source;
        }

        if (source === "extension") {
            await this._initCache();
            const val = this._localCache[key];
            return val as T;
        }

        return new Promise((resolve, reject) => {
            try {
                const item = localStorage.getItem(key);

                if (!item) {
                    resolve("" as T);
                    return;
                }

                try {
                    const result = JSON.parse(item as string);
                    resolve(result as T);
                } catch (error) {
                    resolve(item as T);
                }
            } catch (error) {
                console.error(`[ChromeService] getItem (web) error for key ${key}:`, error);
                reject(error);
            }
        });
    }

    async isExtensionTabOpen(): Promise<boolean> {
        if (!this.isExtension) return false;

        return new Promise((resolve) => {
            const baseUrl = browser.runtime.getURL("#/onboarding");

            browser.tabs.query({}).then((tabs) => {
                const isTabOpen = tabs.some((tab) => tab.url?.startsWith(baseUrl));

                resolve(isTabOpen);
            });
        });
    }

    async openFullPage(path?: string): Promise<void> {
        if (!this.isExtension) return;

        const currentTab = await browser.tabs.getCurrent();

        if (currentTab) return; // No need to open a new tab if running in the current tab

        try {
            const url = browser.runtime.getURL("index.html");
            const targetPath = path ?? window.location.hash.replace(/^#/, "");

            browser.tabs.create({ url: `${url}#${targetPath}` }).then(async (tab) => {
                if (!tab?.id) return;

                try {
                    await this.setItem(this._tabStorageKey, true);
                    await this.setItem("tabId", tab.id);
                } catch (error) {
                    console.error("Failed to update tab state:", error);
                }
            });
        } catch (exception) {
            console.error("Failed to open tab:", exception);
        }
    }

    /** Opens an https URL in a new browser tab (e.g. BlockDAG NFT marketplace). */
    async openExternalUrl(url: string): Promise<void> {
        if (!url?.startsWith("http://") && !url?.startsWith("https://")) return;

        if (!this.isExtension) {
            window.open(url, "_blank", "noopener,noreferrer");
            return;
        }

        try {
            await browser.tabs.create({ url });
        } catch (error) {
            console.error("Failed to open external URL:", error);
        }
    }

    async openSidePanel(): Promise<void> {
        if (!this.isExtension) return;

        const [window] = await browser.windows.getAll({ populate: true });

        if (!window?.id) return;

        if (this.isPopout) {
            const views = browser.extension.getViews({ type: "popup" });

            if (views.length) views[0].close();
        } else {
            const tabs = await browser.tabs.query({ active: true, lastFocusedWindow: true });

            if (tabs.length > 1 && tabs[0].id === this._tabId) await this.closeTab();
        }

        if (!chrome?.sidePanel) return;

        await chrome.sidePanel.open({ windowId: window.id });
    }

    async removeItem(key: string): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.isExtension) {
                browser.storage.local.remove(key).then(resolve).catch(reject);

                return;
            }

            try {
                localStorage.removeItem(key);

                resolve();
            } catch (error) {
                reject(error);
            }
        });
    }

    async setItem(key: string, value: any): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.isExtension) {
                // Update cache immediately
                this._localCache[key] = value;

                browser.storage.local
                    .set({ [key]: value })
                    .then(resolve)
                    .catch(reject);

                return;
            }

            try {
                const isObjectOrArray = typeof value === "object" && value !== null;
                localStorage.setItem(key, isObjectOrArray ? JSON.stringify(value) : value);

                resolve();
            } catch (error) {
                reject(error);
            }
        });
    }

    async setItems(items: Record<string, any>): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.isExtension) {
                // Update cache immediately
                Object.assign(this._localCache, items);

                browser.storage.local.set(items).then(resolve).catch(reject);

                return;
            }

            try {
                for (const [key, value] of Object.entries(items)) {
                    const isObjectOrArray = typeof value === "object" && value !== null;
                    localStorage.setItem(key, isObjectOrArray ? JSON.stringify(value) : value);
                }

                resolve();
            } catch (error) {
                reject(error);
            }
        });
    }

    async clearLocalStorage(): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.isExtension) {
                browser.storage.local.clear().then(resolve).catch(reject);

                return;
            }

            try {
                localStorage.clear();

                resolve();
            } catch (error) {
                reject(error);
            }
        });
    }

    async getItemSession<T = any>(key: string): Promise<T> {
        return new Promise((resolve, reject) => {
            if (this.isExtension) {
                browser.storage.session
                    .get(key)
                    .then((result) => {
                        resolve(result[key] as T);
                    })
                    .catch(reject);
            } else {
                try {
                    const item = sessionStorage.getItem(key);

                    try {
                        if (!item) resolve("" as T);

                        const result = JSON.parse(item as string);

                        resolve(result as T);
                    } catch (error) {
                        resolve(item as T);
                    }
                } catch (error) {
                    reject(error);
                }
            }
        });
    }

    async setItemSession(key: string, value: any): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.isExtension) {
                browser.storage.session
                    .set({ [key]: value })
                    .then(resolve)
                    .catch(reject);
            } else {
                try {
                    const isObjectOrArray = typeof value === "object" && value !== null;
                    sessionStorage.setItem(key, isObjectOrArray ? JSON.stringify(value) : value);

                    resolve();
                } catch (error) {
                    reject(error);
                }
            }
        });
    }

    async removeItemSession(key: string): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.isExtension) {
                browser.storage.session.remove(key).then(resolve).catch(reject);
            } else {
                try {
                    sessionStorage.removeItem(key);

                    resolve();
                } catch (error) {
                    reject(error);
                }
            }
        });
    }

    async clearSessionStorage(): Promise<void> {
        return new Promise((resolve, reject) => {
            if (this.isExtension) {
                browser.storage.session.clear().then(resolve).catch(reject);
            } else {
                try {
                    sessionStorage.clear();

                    resolve();
                } catch (error) {
                    reject(error);
                }
            }
        });
    }
}
